import{_ as o,a0 as p,w as s,s as n,ao as d,I as i,x as l,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Mydumper - MySQL数据库备份工具 | LCTT x X-CMD","titleTemplate":false,"description":"Mydumper - MySQL数据库备份工具 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Mydumper - MySQL数据库备份工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Mydumper - MySQL数据库备份工具 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150326 Mydumper--Mysql Database Backup tool","title":"Mydumper - MySQL数据库备份工具","tag":"201504","desc":""},"relativePath":"201504/20150326 Mydumper--Mysql Database Backup tool.md","filePath":"[post].md"}'),u={name:"201504/20150326 Mydumper--Mysql Database Backup tool.md"};function m(y,e,b,M,h,f){const t=p("Link");return s(),n("div",null,[e[13]||(e[13]=d(`<h1 id="mydumper-mysql数据库备份工具" tabindex="-1">Mydumper - MySQL数据库备份工具 <a class="header-anchor" href="#mydumper-mysql数据库备份工具" aria-label="Permalink to “Mydumper - MySQL数据库备份工具”">​</a></h1><p>Mydumper 是 MySQL 数据库服务器备份工具，它比 MySQL 自带的 mysqldump 快很多。它还有在转储的同时获取远程服务器二进制日志文件的能力。</p><h3 id="mydumper-的优势" tabindex="-1">Mydumper 的优势 <a class="header-anchor" href="#mydumper-的优势" aria-label="Permalink to “Mydumper 的优势”">​</a></h3><ul><li>并行能力 (因此有高速度) 和性能 (高效的代码避免了耗费 CPU 处理能力的字符集转换过程)</li><li>更容易管理输出 (每个表都对应独立的文件，转储元数据等，便于查看/解析数据)</li><li>一致性 ：跨线程维护快照, 提供精确的主从日志定位等。</li><li>可管理性 ： 支持用 PCRE 来包含/排除指定的数据库和表(LCTT译注：PCRE，Perl Compatible Regular Expression，Perl兼容正则表达式)</li></ul><h3 id="在ubuntu上安装-mydumper" tabindex="-1">在Ubuntu上安装 mydumper <a class="header-anchor" href="#在ubuntu上安装-mydumper" aria-label="Permalink to “在Ubuntu上安装 mydumper”">​</a></h3><p>打开终端运行以下命令</p><pre><code>sudo apt-get install mydumper
</code></pre><h3 id="使用-mydumper" tabindex="-1">使用 Mydumper <a class="header-anchor" href="#使用-mydumper" aria-label="Permalink to “使用 Mydumper”">​</a></h3><h4 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to “语法”">​</a></h4><pre><code>mydumper [options]
</code></pre><p>应用程序选项:</p><ul><li>-B, --database 要转储的数据库</li><li>-T, --tables-list 逗号分隔的转储表列表(不会被正则表达式排除)</li><li>-o, --outputdir 保存输出文件的目录</li><li>-s, --statement-size 插入语句的字节大小, 默认是1000000个字节</li><li>-r, --rows 把表按行数切块</li><li>-c, --compress 压缩输出文件</li><li>-e, --build-empty-files 空表也输出文件</li><li>-x, --regex 匹配‘db.table’的正则表达式</li><li>-i, --ignore-engines 以逗号分隔的被忽略的存储引擎列表</li><li>-m, --no-schemas 不转储表架构</li><li>-k, --no-locks 不执行临时共享读锁。警告: 这会导致备份的不一致性</li><li>-l, --long-query-guard 设置长查询的计时器秒数，默认是60秒</li><li>--kill-long-queries 杀死长查询 (而不是退出程序)</li><li>-b, --binlogs 获取二进制日志文件快照并转储数据</li><li>-D, --daemon 开启守护进程模式</li><li>-I, --snapshot-interval 每个转储快照之间的间隔时间(分钟), 需要开启 --daemon, 默认是60分钟</li><li>-L, --logfile 日志文件的名字，默认是stdout</li><li>-h, --host 要连接的主机</li><li>-u, --user 有转储权限的用户名</li><li>-p, --password 用户密码</li><li>-P, --port 连接的TCP/IP端口</li><li>-S, --socket 用于连接的Unix套接字文件</li><li>-t, --threads 使用的线程数，默认是4</li><li>-C, --compress-protocol 在MySQL连接上使用压缩</li><li>-V, --version 查看程序版本号</li><li>-v, --verbose 输出信息的等级, 0 = silent, 1 = errors, 2 = warnings, 3 = info, 默认是2</li></ul><h4 id="mydumper-例子" tabindex="-1">Mydumper 例子 <a class="header-anchor" href="#mydumper-例子" aria-label="Permalink to “Mydumper 例子”">​</a></h4><pre><code>mydumper \\
--database=$DB_NAME \\
--host=$DB_HOST \\
--user=$DB_USER \\
--password=$DB_PASS \\
--outputdir=$DB_DUMP \\
--rows=500000 \\
--compress \\
--build-empty-files \\
--threads=2 \\
--compress-protocol
</code></pre><p>Mydumper 输出数据的说明</p><p>Mydumper 不直接指定输出的文件，而是输出到文件夹的文件中。--outputdir 选项指定要使用的目录名称。</p><p>输出分为两部分</p><p><strong>表结构</strong></p><p>对数据库中的每个表，创建一个包含 CREATE TABLE 语句的文件。文件命名为：</p><p>dbname.tablename-schema.sql.gz</p><p><strong>数据</strong></p><p>每个表名跟着按 --rows 参数所切块的数量, 创建文件名字为:</p><p>dbname.tablename.0000n.sql.gz</p><p>&quot;n&quot;从0开始.</p><p>你可以使用Myloader恢复这些备份</p><pre><code>myloader \\
--database=$DB_NAME \\
--directory=$DB_DUMP \\
--queries-per-transaction=50000 \\
--threads=10 \\
--compress-protocol \\
--verbose=3
</code></pre><hr>`,27)),i("p",null,[e[1]||(e[1]=l("via: ",-1)),r(t,{href:"http://www.ubuntugeek.com/mydumper-mysql-database-backup-tool.html"},{default:a(()=>[...e[0]||(e[0]=[l("http://www.ubuntugeek.com/mydumper-mysql-database-backup-tool.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=l("作者：",-1)),r(t,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:a(()=>[...e[2]||(e[2]=[l("ruchi",-1)])]),_:1}),e[6]||(e[6]=l(" 译者：",-1)),r(t,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[3]||(e[3]=[l("ictlyh",-1)])]),_:1}),e[7]||(e[7]=l(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[l("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=l("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[l("LCTT",-1)])]),_:1}),e[11]||(e[11]=l(" 原创翻译，",-1)),r(t,{href:"http://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[l("Linux中国",-1)])]),_:1}),e[12]||(e[12]=l(" 荣誉推出",-1))])])}const C=o(u,[["render",m]]);export{x as __pageData,C as default};
